#include "stdlib/blas/base/srotmg.h"
#include <stdio.h>

int main( void ) {
	// Specify rotational elimination parameter:
	const float d1 = 5.0;
	const float d2 = 4.0;
	const float x1 = 1.0;
	const float y1 = -2.0;
	int i;

	// Create strided arrays:
	float out[ 5 ];

	// Specify stride lengths:
	const int stride = 1;

	// Apply plane rotation:
	c_srotmg( d1, d2, x1, y1, out, stride );

	// Print the result:
	for ( i = 0; i < 5; i++ ) {
		printf( "out[%d] =  %f\n", i, out[ i ] );
	}

	// Apply plane rotation
	c_srotmg_assign( d1, d2, x1, y1, out, stride, 0 );

	// Print the result:
	for ( i = 0; i < 5; i++ ) {
		printf( "out[%d] =  %f\n", i, out[ i ] );
	}
}
